const trackGoogleSearch = () => {
  chrome.runtime.sendMessage({
    type: 'trackAnalytics',
    events: [
      {
        variant: 'event',
        payload: [
          'V2_Google_Search',
          {
            platform:
              process.env.APP_TYPE === 'search' ||
                process.env.APP_PLATFORM === 'web'
                ? 'omnibox'
                : 'ntp',
          },
        ],
      },
    ],
  });
};

