import { FunctionalComponent, render } from 'preact';
import { useState } from 'preact/hooks';
import { getStorageItems, setStorageItems } from '../../../../../shared/chromeApi';

import MoreButton from '../../../../../shared/MoreButton';
import { ContentAds } from '../../../interfaces';
import styles from './styles.module.scss';

const DICT = {
  annotations: {
    storageKey: 'isButtonHidden',
    label: 'Hide “help the ocean” buttons on searches',
    disableEvent: 'Google_shells_disabled',
  },
  sidebar: {
    storageKey: 'isSidebarHidden',
    label: 'Hide “sidebar ads”',
    disableEvent: 'Google_sidebar_ads_disabled',
  },
  tiles: {
    storageKey: 'isTilesHidden',
    label: 'Hide “tiles ads”',
    disableEvent: 'Google_tiles_disabled',
  },
  counter: {
    storageKey: 'isCounterHidden',
    label: 'Hide counter',
    disableEvent: 'Google_counter_disabled',
  },
};


interface Props {
  variant: 'annotations' | 'sidebar' | 'tiles' | 'counter',
  style?: any,
  styleTooltip?: any,
  className?: string,
  size?: 'small',
}

const ContextMenu: FunctionalComponent<Props> = ({ variant, style, size, className, styleTooltip }: Props) => {
  const [showContextMenu, setShowContextMenu] = useState(false);

  const hideAllGoogleShellsButtons = async (): Promise<void> => {
    const storage = await getStorageItems<{contentAds: ContentAds}>(['contentAds']);
    const contentAds = storage.contentAds || {};

    await setStorageItems({
      contentAds: { ...contentAds, [DICT[variant].storageKey]: true },
    });

    const $elements = document.querySelectorAll(`[data-oh-id="${variant}"]`);
    $elements.forEach(($el) => {
      render(null, $el);
    });

    chrome.runtime.sendMessage({
      type: 'trackAnalytics',
      events: [
        {
          variant: 'event',
          payload: [DICT[variant].disableEvent, { category: 'Google_shells' }],
        },
      ],
    });
  };

  return (
    <div className={`${styles.contextMenuContainer} ${className || ''}`} style={style}>
      <MoreButton
        className={`${styles.contextMenuBtn} ${showContextMenu ? styles.selected : ''} ${size && styles[size]}`}
        onClick={(): void => setShowContextMenu((prev) => !prev)}
      />

      {showContextMenu && (
        <div
          style={styleTooltip}
          className={styles.contextMenuOverlay}
          onMouseLeave={(): void => {
            setShowContextMenu(false);
          }}
        >
          <div className={styles.contextMenu}>
            <ul>
              <li onClick={hideAllGoogleShellsButtons}>
                <div className={styles.hideShells}>{DICT[variant].label}</div>
              </li>
              <li>
                <a
                  rel="noreferrer"
                  target="_blank"
                  // href="https://docs.google.com/forms/d/e/1FAIpQLScRvDM0RkiCrSRpZP_dLSTLm7SaAzhj9HVHbhiklXFjWXXWPg/viewform?usp=sf_link"
                  href="https://docs.google.com/forms/d/e/1FAIpQLSffkyLiA1eVU-F8gSKhV3Muh_zwIj876yOPZX68ozA_jWb1PA/viewform?usp=sf_link"
                >
                  Give feedback
                </a>
              </li>
            </ul>
            <div className={styles.byOh}>by OceanHero</div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ContextMenu;
